INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Hint`, `Sources`) VALUES
(137700, 0, 1377, 0, 0, 0, 'Silithus', 'Silithus is a wasteland of sand, wind and stone in the far southwest of Kalimdor, reached on foot only from Un''Goro. Nearly a thousand years ago the qiraji poured out of their city of Ahn''Qiraj and swept across this desert, until they were sealed behind the Scarab Wall in the south. Now the silithid hives swarm once more, the Cenarion Circle keeps watch from Cenarion Hold, and the Twilight''s Hammer camps across the sands.', '', 'warcraft.wiki.gg/wiki/Silithus (only land route through northwestern Un''Goro; Cenarion Hold; silithyst world PvP); quest 1124 description (west of Un''Goro via the northwestern ridge); quests 8275, 8276, 8507, 8731 (Horde and Alliance volunteers); DB: gameobject 49390-49392 state 0, no game_event_gameobject rows; creature 15499, 15500 permanent; quest 1124 description (an ancient war between the night elves and a malign alien power, sealed); aq_gate_quest.sql (module gate 176146-176148 seen before state 5); warcraft.wiki.gg/wiki/War_of_the_Shifting_Sands (Scarab Wall sealing)'),
(137705, 1, 1377, 0, 0, 0, 'Cenarion Hold', 'Cenarion Hold is the fortress of the Cenarion Circle at the heart of Silithus, raised where an old night elf settlement stood, to guard against what lies sealed in the south. Its infantry deal harshly with anyone who spills blood on neutral ground, and a bronze drake circles overhead.', '', 'warcraft.wiki.gg/wiki/Cenarion_Hold (Circle took over the ancient night elven settlement, set up after the war to guard C''Thun; leaders Mar''alith and Vish Kozus); creature_text 15184 (You dare spill blood on neutral ground?); quest 8283 description (Vish Kozus at the top of the watchtower); quest 8280 description; npc_text 7731 (Baristolth''s promise); zone_areas 3425: Cloud Skydancer 15177, Runk Windtamer 15178, Brood of Nozdormu 15185; quest 8307 description (misses Auberdine; bitter sandworm meat); npc_text 7732; quest 8304 description and reward text; npc_text 7733 (Vish Kozus: the Commander has not been himself); warcraft.wiki.gg/wiki/Commander_Mar''alith (night elf warrior, head of the Circle''s forces); quests 8287, 8498 (intelligence on the cult turned in to him); quest 8286 description and reward text; npc_text 7731; creature_text 15180 (the Brood of Nozdormu have returned); warcraft.wiki.gg/wiki/Baristolth_of_the_Shifting_Sands (night elf, Watcher of the bronze dragonflight); npc_text 7734; warcraft.wiki.gg/wiki/Geologist_Larksbane (female dwarf, Cenarion Circle); quest 8284 description; quest 8314 description; quest 8304 description; quests 8309, 8310 descriptions'),
(137707, 1, 1377, 0, 0, 0, 'The Crystal Vale', 'In the far northwest of Silithus lies the Crystal Vale, ruled by elementals of earth and air, and within it the ravaged remains of a Twilight''s Hammer camp. A lone human, Highlord Demitrian, keeps vigil there, and to those who pass he says only this: look to this ravaged field and know the power that the elements hold.', '', 'warcraft.wiki.gg/wiki/Crystal_Vale (far northwestern corner, earth and air elementals, thorium, Ravaged Twilight Camp, Demitrian); zone_areas 2740 and 3100: Desert Rumbler, Dust Stormer, Huricanian 14478 (rank 4), Twilight Tablet Fragment; quest 8284 description (camp once thrived, elementals, wood and canvas); quest 6805 (Azshara, Hydraxis: Stormers and Rumblers); npc_text 6812 (Demitrian); npc_text 6812, 6843, 6844, 6867-6870, 6954-6958; quests 7785, 7786 reward text, 7787 description (lying wretch, his betrayal); warcraft.wiki.gg/wiki/Highlord_Demitrian (human, Ravaged Twilight Camp, Crystal Vale); quest 8284 description'),
(137708, 1, 1377, 0, 0, 0, 'Southwind Village', 'In eastern Silithus lie the ruins of Southwind Village, once the night elves'' base in this land. It fell in the War of the Shifting Sands and the silithid have held it ever since. The tortured spirits of fallen druids and sentinels still wander its streets, and their death wails rouse the hive that has claimed the village tower.', '', 'quest 1125 description and reward text; quest 1126 description (tower with the mass of wasps); creature_text 12178/12179 (death wail stirs the hive); warcraft.wiki.gg/wiki/Southwind_Village (spirits led by the Shade of Ambermoon); npc_text 7783 (Aendel: the ghostly figure looks at you with mistrust); quest 5527 description (Reliquary of Purity at Southwind); warcraft.wiki.gg/wiki/War_of_the_Shifting_Sands (Southwind fell); quest 1125 description and request text; quest 1124 reward text'),
(137711, 1, 1377, 0, 0, 0, 'Hive''Regal', 'Hive''Regal is the southern hive of Silithus, haunt of slavemakers, spitfires and hive lords, and like its sister hives of Ashi and Zora it guards a crystal carved with qiraji glyphs. Deep in its tunnels a Cenarion scout creeps close enough to the insects to go unnoticed, though he would not advise anyone to try it.', '', 'zone_areas 2744: Hive''Regal Slavemaker, Spitfire, Hive Lord, Ambusher, Burrower, Lapress 14473, Krug Skullsplit 15612, Merok, Kirika''s camp 17079; warcraft.wiki.gg/wiki/Hive''Regal (southern Silithus, Natalia, Landion); npc_text 8059 (Krug); quest 8731 reward text (signed in silithid blood); quest 9422 description; npc_text 8063 (Landion); quest 8306 objectives; zone_areas 2744: Stonelash Flayer, Rock Stalker; gameobject 180453 Hive''Regal Glyphed Crystal; quest 8304 description'),
(137712, 1, 1377, 0, 0, 0, 'Bronzebeard Encampment', 'In the southern hills of Silithus, east of the Scarab Wall, the dwarves of Brann Bronzebeard''s expedition have made camp to search the hives for lost artifacts; between the four of them, monkey included, they speak thirty-eight languages. Brann himself has gone missing again, and his companions'' pleas to Ironforge for an army go unanswered.', '', 'warcraft.wiki.gg/wiki/Bronzebeard_Encampment (southern Silithus, east of the Scarab Wall); npc_text 7755, 7764, 7761 (artifacts, 38 languages, requests to Ironforge); npc_text 7736 (Bronzebeard''s gone missing again); quests 8282, 8283 (Deathclasp in the southern mountain range behind Bronzebeard''s camp); creature 15172 Glibb <Brann Bronzebeard''s Pet Monkey>; npc_text 7761 (onto something huge)'),
(137714, 1, 1377, 0, 0, 0, 'The Scarab Wall', 'In the far southwest of Silithus runs the Scarab Wall, raised at the end of the War of the Shifting Sands to seal the qiraji and their silithid within Ahn''Qiraj. In it stand the gates of the fortress city, bound for a thousand years by great roots and glowing runes, and before them rises the Scarab Dais. Near the wall lies a single crystalline tear, left as a symbol of the great losses of that war.', '', 'warcraft.wiki.gg/wiki/Scarab_Wall (molded from the sand, bronze dragonflight barrier many times taller); quest 8305 description and reward text (crystalline tear near the sacred barrier); zone_areas 2737: Crystalline Tear 180633, Setis 14471, Stonelash Flayer; quest 8743 request text (the Scarab Gong, slackened maw); warcraft.wiki.gg/wiki/Gates_of_Ahn''Qiraj (gates stayed open, Ruins and Temple beyond); DB: gate doors 180904/180898/180899 spawn state 0 (open); posarea: 3478 at -8200,1530 west of the door, 2741 at the gong');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(137700, 1, 3, 255, 'The Circle calls for help: the silithid, too long unchecked, are readying to spread, and volunteers of both factions pour into Cenarion Hold.', ''),
(137700, 2, 4, 4, 'The Scarab Gong has sounded. The qiraji pour out upon the desert, resonating crystals burst through the earth and colossi of obsidian stone have risen at the three hives.', ''),
(137700, 3, 5, 255, 'The gates of Ahn''Qiraj stand open and the war has been carried inside, where the fighting goes on day and night.', ''),
(137705, 1, 3, 255, 'The hold has filled for war under Commander Mar''alith, whose beloved Natalia has gone missing after weeks of talking to someone no one else could see. Among the tents a night elf, Baristolth, waits on a promise a thousand years old.', ''),
(137705, 2, 3, 255, 'Natalia was found deep in Hive''Regal, become the High Priestess of C''Thun. The grieving commander could only ask what C''Thun was.', 'warcraft.wiki.gg/wiki/Cenarion_Hold (Circle took over the ancient night elven settlement, set up after the war to guard C''Thun; leaders Mar''alith and Vish Kozus)'),
(137705, 3, 3, 255, 'A dwarven geologist unlocked a glyphed prism of the hives and found twenty thousand years of history in it, and a prophecy that, should it come to pass, could mean the end of every future.', 'warcraft.wiki.gg/wiki/Cenarion_Hold (Circle took over the ancient night elven settlement, set up after the war to guard C''Thun; leaders Mar''alith and Vish Kozus)'),
(137707, 1, 0, 255, 'A diary decoded from the camp''s clay tablets tells of pilgrims who raised a wind stone to speak with their masters, and readied the rituals to summon Baron Kazum himself. There the diary ends.', 'warcraft.wiki.gg/wiki/Crystal_Vale (far northwestern corner, earth and air elementals, thorium, Ravaged Twilight Camp, Demitrian)'),
(137707, 2, 0, 255, 'Demitrian serves Thunderaan, Prince of Air, betrayed in the Elemental Sundering by Ragnaros''s lieutenants Geddon and Garr, struck down by the Firelord and fed upon; what remained was sealed in a talisman, broken in two.', 'warcraft.wiki.gg/wiki/Crystal_Vale (far northwestern corner, earth and air elementals, thorium, Ravaged Twilight Camp, Demitrian)'),
(137708, 1, 0, 255, 'Southwind''s fall has a name the night elves still mourn. Fandral Staghelm ordered his son Valstann to defend the village, and Valstann died there on the day it fell.', 'quest 1125 description and reward text'),
(137711, 1, 0, 255, 'Somewhere in its depths is Natalia Mar''alith. The dwarves saw her run into the hive after her madness took her, and not one insect tried to bar her way.', 'zone_areas 2744: Hive''Regal Slavemaker, Spitfire, Hive Lord, Ambusher, Burrower, Lapress 14473, Krug Skullsplit 15612, Merok, Kirika''s camp 17079'),
(137711, 2, 4, 4, 'The war has reached the hive: the Colossus of Regal has risen, and a great resonating crystal of the qiraji has broken through the sand before it.', ''),
(137712, 1, 0, 255, 'A letter in Brann''s hand tells of a great battle between a titan and an Old God, a bona fide one, and of an ancient tunnel into Ahn''Qiraj that he meant to take.', 'warcraft.wiki.gg/wiki/Bronzebeard_Encampment (southern Silithus, east of the Scarab Wall)'),
(137714, 1, 0, 255, 'Those who gaze into the tear feel a sorrow so heavy they fear they might die of it, and in its depths a long forgotten memory of the old war stirs.', 'warcraft.wiki.gg/wiki/Scarab_Wall (molded from the sand, bronze dragonflight barrier many times taller)'),
(137714, 2, 4, 4, 'The gong has been rung. Roots, runes and the great doors gave way, and the qiraji came out to meet the world.', ''),
(137714, 3, 5, 255, 'Now nothing bars the way through the wall, and the Circle''s allies carry the war into the ruined city and on toward the temple beyond.', '');
