INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Hint`, `Sources`) VALUES
(2800, 0, 28, 0, 0, 0, 'Western Plaguelands', 'The Western Plaguelands were the heart of northern Lordaeron, a country of farms and forests governed from Hearthglen, with Andorhal as the granary of the north. That bounty undid it. The Cult of the Damned tainted the grain, the plague killed the people and raised them as Scourge, and great cauldrons still poison the fields. Now a lich rules Andorhal, Scholomance festers beneath Caer Darrow and the Scarlet Crusade holds Hearthglen, while the Alliance at Chillwind Camp and the Forsaken at the Bulwark hold on at the edges.', '', 'warcraft.wiki.gg/wiki/Western_Plaguelands (pre-Cataclysm: Hearthglen seat, Andorhal grain hub, cult tainted grain, four cauldrons on largest farmsteads, tumor-like growths, Scarlet Crusade in Mardenholde); quest 105 and 211 descriptions (Araj holds Andorhal); quest 838 description (Scholomance on Caer Darrow); quest 6004 reward text (Crusade kills anyone not loyal, even innocents); npc_text 4134, 4135 (Argent Dawn calls Horde and Alliance friends); quests 5066, 5093 (Chillwind Camp and the Bulwark)'),
(2801, 1, 28, 0, 0, 0, 'Chillwind Camp', 'Chillwind Camp, on the southern edge of the plague lands below the Alterac Mountains, is the Alliance''s foothold in the west. Commander Ashlam Valorfist holds it for Stormwind and plans the push on Andorhal, High Priestess MacDonnell leads the war on the plague cauldrons, and officers of the Argent Dawn sign up anyone willing to fight the dead. The camp also shelters Weldon Barov, a nobleman feuding with his own brother.', '', 'quest 5066 description (base camp north of the Alterac Mountains); warcraft.wiki.gg/wiki/Chillwind_Camp (last bastion of safety for Alliance travelers); npc_text 3754 (Valorfist gossip); quests 5215, 5217, 5533 (MacDonnell his second, Arbington); quest 5401 reward text (Argent Dawn commission); quest 6184 (Flint Shadowmore stationed at Chillwind); quest 5342 (Weldon under Alliance protection at Chillwind Camp); zone_areas: all these NPCs stand in area 3197; npc_text 3754 (Valorfist gossip); quests 5092, 5097, 211; quests 5215, 5533; quests 8414, 8416, 8418 (Holy Mightstone, righteous fire); quest 5237 reward text; creature_template 10838 faction 123 (Stormwind); creature_queststarter: 8418 Forging the Mightstone starts at Valorfist 10838'),
(2802, 1, 28, 0, 0, 0, 'Sorrow Hill', 'Sorrow Hill is the great cemetery south of Andorhal, where the city buried its dead long before the plague. They do not rest: skeletons and ghouls rise from the graves to guard the road to the city. Atop the hill stands the tomb of Uther the Lightbringer, and among the graves the monument of Captain Joseph Redpath of Darrowshire.', '', 'warcraft.wiki.gg/wiki/Sorrow_Hill (large cemetery south of Andorhal used for burials from Andorhal and around it; Redpath monument); quest 5092 description (Scourge buffer at Sorrow Hill, less defended eastern road); zone_areas area 197: Skeletal Flayer, Slavering Ghoul, Skeletal Sorcerer, Lord Maldazzar 1848 (rare), Marlene Redpath 10927, Myranda 11872, Joseph Redpath''s Monument 176145; quest 5153 description (body trampled and destroyed years ago); quest 5152 (Marlene lives in a house on a hill south of Andorhal); quest 5861 (Myranda resides at Uther''s tomb), 5861 reward text (banished); page_text 2372 (Captain Joseph Redpath of Darrowshire); quest 5142 description (so many died, and worse; hid her niece Pamela; Darrowshire to the east beyond Gahrron''s Withering); quest 5152 (house on a hill south of Andorhal); gameobject 176145 Joseph Redpath''s Monument; page_text 2372 (Captain Joseph Redpath of Darrowshire); posarea: Marlene 10927 in area 197; quest 5153 description'),
(2803, 1, 28, 0, 0, 0, 'Uther''s Tomb', 'Uther the Lightbringer, first paladin of the Order of the Silver Hand, fell to his own student, Prince Arthas, and the survivors raised his tomb atop Sorrow Hill. Its epitaph says that he lived and died to defend Lordaeron. High Priest Thel''danis keeps watch over it and purges the evil from the scourgestones brought to him.', '', 'page_text 292 (gameobject 2082, Uther''s epitaph); warcraft.wiki.gg/wiki/Sorrow_Hill (survivors built the tomb atop the cemetery hill); warcraft.wiki.gg/wiki/Uther%27s_Tomb (Thel''danis caretaker, Mark of the Lightbringer); quest 8414 description (Thel''danis guarding Uther''s Tomb), 8416 description (evil purged from the stones); quests 9474, 9446 and creature_text 17233 (Ghost of Uther); quests 9443, 9444 (Mehlar Dawnblade); posarea: Thel''danis 1854 in area 196; quest 5861 reward text (advisor, dissent, banished); quest 6568 description and reward text (master illusionist of Lordaeron, Rexxar, owes the Warchief); quest 5862 description (illusion limits); npc_text 4633, 4773; posarea: Myranda 11872 in area 197; warcraft.wiki.gg/wiki/Myranda_the_Hag; quests 9474, 9446 (descriptions and reward texts); quests 9443, 9444 (descriptions and reward texts); creature_text 17233 (Ghost of Uther), 17238, 17099; creature_template 17238 Anchorite Truuen (draenei per quest 9474: in the short time I have been on Azeroth)'),
(2804, 1, 28, 0, 0, 0, 'Caer Darrow', 'Caer Darrow, an old fortress on an island in Darrowmere Lake, was the seat of House Barov. To keep their lands beyond their own lifetimes the Barovs struck a bargain with Kel''Thuzad, and beneath the keep grew Scholomance, a school of necromancy. A sickness born there killed the whole town on the eve of a visit from Uther, and its people linger as ghosts, reliving their last ordinary day.', '', 'warcraft.wiki.gg/wiki/Caer_Darrow (Barov seat, deal with Kel''Thuzad, Scholomance, plague before Uther''s visit, no survivors, ghosts reliving last memory, lake lifeless and still); npc_text 4118 (citizens preparing for Uther''s visit); creature_text 11282, 11283 (Melia and Sammy racing); zone_areas area 2298: Baker Masterson, guardsmen, cannoneers, citizens, Marduke, Renfray; quest 5846 description and reward text (Renfray: few that remember all); quests 5461, 5466 (Marduke and Ras Frostwhisper); AreaTable: 2297 Darrowmere Lake, 2298 Caer Darrow; posarea: Renfray 11936, Eva 11216, Marduke 11286 in area 2298; quests 5341, 5343 descriptions (deeds to Caer Darrow, Brill, Tarren Mill, Southshore; Weldon fled the war and remains human; Weldon regrets sparing Alexi); quests 5342, 5344 descriptions (each sheltered by a faction; each wants the other''s head); creature_template 11022 faction 83 (Undercity), 11023 faction 123 (Stormwind); warcraft.wiki.gg/wiki/Caer_Darrow (Barov deal with Kel''Thuzad); npc_text 4041 (Eva gossip); quests 5382, 5515, 5384 descriptions and reward texts (Krastinov, burn our remains, Kirtonos, piece of our essence); item 13544 Spectral Essence (communication with the deceased of Caer Darrow); warcraft.wiki.gg/wiki/Eva_Sarkhoff (head maid and butler of the Barovs, experimented on by Krastinov); warcraft.wiki.gg/wiki/Caer_Darrow (servants used as experiments)'),
(2805, 1, 28, 0, 0, 0, 'Ruins of Andorhal', 'Andorhal was the grain distribution center of northern Lordaeron, which made it the perfect tool for the Cult of the Damned: tainted grain went out from its granaries to the villages of the north, and the city soon fell. Here Prince Arthas cut down Kel''Thuzad. Now a Scourge garrison fills the streets under the lich Araj the Summoner, once master of Scholomance, and a small gnome named Chromie has taken lodging in a ruined inn.', '', 'warcraft.wiki.gg/wiki/Andorhal (grain distribution point, cult infected grain sent to northern villages, Araj headquarters); zone_areas area 193: Skeletal Acolyte, Skeletal Executioner, Searing and Soulless Ghouls, Flesh Golem, Araj 1852, Chromie 10667, Andorhal Tower One to Four; quests 5097, 5098 (watchtowers control troop movements); quest 5803 (Araj lords over Andorhal from the city''s heart); quest 5153 (Chromie in the ruined inn at the northwest corner); quest 5154 (Annals of Darrowshire in the city hall); quests 4971, 4972; quests 105, 211 descriptions and reward texts; quests 5803, 5804 descriptions (former leader of Scholomance, scarab seized from his fallen phylactery); warcraft.wiki.gg/wiki/Araj_the_Summoner (headmaster of Scholomance, Andorhal headquarters, oversaw the cauldrons; phylactery appears in place of his corpse); creature 1852 faction 21 (Scourge), area 193; quests 5092, 5096, 5097, 5098, 105, 211 (descriptions, request and reward texts)'),
(2806, 1, 28, 0, 0, 0, 'Felstone Field', 'Felstone Field, northwest of Andorhal, is one of four farms where the Scourge raised a great plague cauldron, guarded here by Cauldron Lord Bilemaw. Upstairs in the farmhouse the ghost of Janice Felstone cowers in a corner, frantic to send off a parcel she packed before the plague came. Nearby the Scarlet Crusade has pitched a camp of its own.', '', 'quests 5216, 5229 descriptions (northwest of Andorhal, greener troops, should not be underestimated); quest 5216 reward text (Cauldron Lord Bilemaw); quest 5021 description and reward text (ghost upstairs, package in the barn); quest 5096 description (Scarlet camp between Felstone Field and Dalson''s Tears); zone_areas area 199: Command Tent 176210, Scourge Cauldron 176361, Janice Felstone 10778, Janice''s Parcel, Scarlet Hunter/Medic/Invoker; warcraft.wiki.gg/wiki/Felstone_Field (Scarlet party attacked players and Scourge); quest 5021 description and reward text; quests 5022, 5023 descriptions (addressed to Emma Felstone of Stormwind or Jeremiah Felstone of Lordaeron); quest 5048 reward text (Emma: my sister); quest 5050 description (personal effects, deed, half charm, husband had the other half); quest 5051 description and reward text (John; freed); npc_text 3668 (Janice gossip: time is running out); quest 5050 reward text (half-charm returned; where did you put your half)'),
(2807, 1, 28, 0, 0, 0, 'Dalson''s Tears', 'North of Andorhal lies the farm once called Dalson''s Orchard. The Scourge raised a plague cauldron in its field under Cauldron Lord Malvinious, and the farm keeps smaller horrors of its own: a diary open in the house, a lone skeleton wandering the grounds, and an outhouse locked from outside, its door splintered by something within that batters to get out.', '', 'warcraft.wiki.gg/wiki/Dalson%27s_Tears (formerly Dalson''s Orchard; Cauldron Lord Malvinious; Mrs. Dalson roams as a Wandering Skeleton); quests 5219, 5231 (almost due north of Andorhal); quest 5058 reward text (Mrs. Dalson''s Diary); quests 5059, 5060 request and reward texts (splintered outhouse door, key on her skeleton, scratched cabinet, key on the ghoul); zone_areas area 200: Rotting Cadaver, Blighted Zombie, Skeletal Terror, Wandering Skeleton 10816, Outhouse, Locked Cabinet, Mrs. Dalson''s Diary; wiki cites Arthas: Rise of the Lich King p. 215 for the old name Dalson''s Orchard (2009, pre-Cataclysm)'),
(2808, 1, 28, 0, 0, 0, 'The Writhing Haunt', 'East of Andorhal, under the city walls, a farm has become the Writhing Haunt, its plague cauldron guarded by Cauldron Lord Razarch. In one of its cottages lies Mulgris Deepriver, a tauren druid who came alone to heal what the Scourge had poisoned. The plague took him too, and blind and dying he asks strangers to give the diseased wolves and grizzlies a merciful death.', '', 'quests 5222, 5233 descriptions (almost due east of Andorhal, close to the ruined city walls); warcraft.wiki.gg/wiki/The_Writhing_Haunt (Cauldron Lord Razarch; Mulgris hidden inside a house); zone_areas area 202: Rotting Ghoul, Freezing Ghoul, Fetid Zombie, Mulgris Deepriver 10739, Scourge Cauldron 176393; npc_text 3634; quests 4984, 4985; npc_text 3634 (put aside your differences, dying plea); quests 4984, 4985 descriptions, request and reward texts (succumbed to the plague, vision faded, his death); quests 4986, 4987 (Glyphed Oaken Branch to the Cenarion Circle; Nara Wildmane: a good friend, lore about the plague)'),
(2809, 1, 28, 0, 0, 0, 'Gahrron''s Withering', 'Gahrron''s Withering, once Gahrron''s Quickening, was the farm of Del Gahrron near the border of the Eastern Plaguelands. Its plague cauldron is the hardest of the four in the west: no ghouls shamble here, only wraiths and wailing spirits around Cauldron Lord Soulwrath. Beside the barn lies a forgotten shield once carried by Joseph Redpath of Darrowshire.', '', 'warcraft.wiki.gg/wiki/Gahrron%27s_Withering (formerly Gahrron''s Quickening, owned by Del Gahrron, Soulwrath, Joseph Redpath killed here, his shield); quests 5225, 5235 descriptions (last cauldron, tougher minions, wraiths and ghosts, close to where the Eastern Plaguelands begin); quest 5225 reward text (Cauldron Lord Soulwrath); zone_areas area 201: Hungering Wraith, Wailing Death, Haunting Vision, Redpath''s Shield 176207; page_text 2386 (The Fate of Joseph Redpath, Extended Annals of Darrowshire: defeated at Gahrron''s Withering, shield near the barn); wiki cites Arthas: Rise of the Lich King p. 215 for the old name Gahrron''s Quickening (2009, pre-Cataclysm)'),
(2812, 1, 28, 0, 0, 0, 'Hearthglen', 'Hearthglen was the seat of government for these lands, ruled from Mardenholde Keep above the town, and when the plague first struck it held out against the Scourge. Now it is the Scarlet Crusade''s stronghold in the west. Workers rebuild the town under the eyes of paladins and priests, lumberjacks cut timber at the Northridge mill below, taken from the family who ran it before the war, and Highlord Taelan Fordring holds the keep.', '', 'warcraft.wiki.gg/wiki/Hearthglen (regional seat; held off a Scourge siege until Uther arrived; Scarlet Crusade took control); zone_areas area 190: Scarlet Worker x56, Scarlet Paladin, Sentinel, Magus, Priest, High Protector Lorik, Taelan; quest 6023 description (Radley and Durgen the backbone of the forces outside the town, along Hearthglen Pass); quest 9474 description (relic atop their guard tower near the gates); quest 6004 description (Alliance feel the town has more than historical importance); quest 6025 reward text (Kirsta reports to Stormwind); warcraft.wiki.gg/wiki/Hearthglen (region governed from Mardenholde Keep; center of commerce and trade; Alliance diplomats; Tirion Lord of Mardenholde); warcraft.wiki.gg/wiki/Western_Plaguelands (Scarlet Crusade took Mardenholde Keep as regional headquarters); quest 5861 reward text (Myranda, advisor when Tirion was Lord of Mardenholde, dissented from the Silver Hand''s verdict, banished); quest 5862 log and request text (Taelan inside Mardenholde Keep; reinforcements from Tyr''s Hand); warcraft.wiki.gg/wiki/Mardenholde_Keep; zone_areas area 190 (Scarlet workers, paladins, sentinels); quest 5901 description (defending and rebuilding the town); quests 5902, 5904 descriptions (south of Hearthglen, west of the road); npc_text 4357 (Nathaniel Dumah: father ran the mill, fled to Stormwind); npc_text 4356 (Mickey Levine: family worked the mill); quest 5901 description (defending and rebuilding the town); zone_areas area 192: Scarlet Lumberjack x25, Diseased Wolf, Carrion Lurker, Foreman Marcrid'),
(2816, 2, 28, 0, 0, 0, 'Highlord Taelan Fordring', 'Taelan Fordring is Highlord of the Scarlet Crusade in Hearthglen and master of Mardenholde Keep. His crusaders attack outsiders on sight, his officers hold the pass below the town, and the Highlord himself waits in the keep for reinforcements from Tyr''s Hand.', '', 'quest 5781 description (his mother told him Tirion had died); quest 5845 description (fought on until the Silver Hand was destroyed); creature_template 1842 subname Highlord of the Scarlet Crusade, faction 67 (Scarlet Crusade, hostile to both factions), npcflag questgiver; quest 5861 description (Taelan and his Scarlet Crusaders attack on sight); quest 6023 description (Radley and Durgen hold Hearthglen Pass); quest 5862 log and request text (inside Mardenholde Keep; reinforcements from Tyr''s Hand); warcraft.wiki.gg/wiki/Taelan_Fordring; warcraft.wiki.gg/wiki/Hearthglen (Taelan took control of the town); zone_areas area 190 (Scarlet Worker, Paladin, Sentinel, Magus, Priest); quest 5862 log and reward text (Scarlet Illusion, Mardenholde Keep); quest 5944 description and reward text; creature_text 1842, 1840 (Isillien: forest''s edge, Grand Crusader charged me), 12126 (murdered my boy; too long have I sat idle; a new Order is born); warcraft.wiki.gg/wiki/Tirion_Fordring (Isillien killed Taelan in Hearthglen; Tirion avenged his son); creature_text 1840 group 0 (you will not make it to the forest''s edge)'),
(2817, 2, 28, 0, 0, 0, 'Chromie', 'Chromie is the name the bronze dragon Chronormu takes among mortals, in the form of a small, cheerful gnome. She has made her home in a ruined inn in Andorhal, working from another timeline so as not to disturb this one, for someone, most likely the Scourge, has tampered with the city''s past. The old tragedy of Darrowshire has caught her eye as well.', '', 'npc_text 3584, 3585 (Chronormu, bronze dragonflight, choice of visual demeanor, sentry of sorrowful places); quests 4971, 4972 descriptions and texts; quest 5153 (strange gnome, ruined inn of Andorhal); quests 5154, 5941, 5721 (saving Joseph Redpath)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(2802, 1, 0, 255, 'The ghost of Marlene Redpath haunts her old house on the hill. When the battle of Darrowshire began she hid her young niece, Pamela, and she has never learned what became of the girl.', 'warcraft.wiki.gg/wiki/Sorrow_Hill (large cemetery south of Andorhal used for burials from Andorhal and around it; Redpath monument)'),
(2803, 1, 0, 255, 'Within sight of the tomb lives Myranda the Hag, a master illusionist banished from Mardenholde Keep for speaking against a verdict of the Silver Hand. She still weaves guises for those she trusts, and not all of them are Alliance.', 'page_text 292 (gameobject 2082, Uther''s epitaph)'),
(2803, 2, 0, 255, 'The verdict she spoke against was the one that banished Tirion Fordring. She had been his most trusted advisor when he was Lord of Mardenholde, and she always knew he would call on her again.', 'page_text 292 (gameobject 2082, Uther''s epitaph)'),
(2803, 3, 8, 255, 'Uther''s holy mark was lost when he died, and the Scarlet Crusade keeps it in Hearthglen. A draenei anchorite at Chillwind Camp wants it returned to the tomb; a blood knight at the Bulwark, once Uther''s student, wants it for revenge for Quel''Thalas.', 'page_text 292 (gameobject 2082, Uther''s epitaph)'),
(2803, 4, 8, 255, 'Brought to the tomb, the mark called up Uther''s own ghost. He blessed those who came to honor him, and to the student who meant to defile his tomb he sent only forgiveness.', 'page_text 292 (gameobject 2082, Uther''s epitaph)'),
(2804, 1, 0, 255, 'The last Barov heirs are brothers and bitter rivals. Alexi stayed with the family and is now undead, lounging under Horde guard at the Bulwark; Weldon fled and lives under Alliance guard at Chillwind Camp. The deeds to the family fortune lie in Scholomance.', 'warcraft.wiki.gg/wiki/Caer_Darrow (Barov seat, deal with Kel''Thuzad, Scholomance, plague before Uther''s visit, no survivors, ghosts reliving last memory, lake lifeless and still)'),
(2804, 2, 0, 255, 'The spirits of Eva and Lucien Sarkhoff, servants of the Barovs, linger on the island. When the family turned, its servants became subjects for the Butcher, Doctor Theolen Krastinov, and the Sarkhoffs died in his hands.', 'warcraft.wiki.gg/wiki/Caer_Darrow (Barov seat, deal with Kel''Thuzad, Scholomance, plague before Uther''s visit, no survivors, ghosts reliving last memory, lake lifeless and still)'),
(2805, 1, 0, 255, 'Araj was brought down at last, though a lich is not so easily ended: from the phylactery left where he fell, a shard was carried home as proof that the lord of Andorhal was overthrown.', 'warcraft.wiki.gg/wiki/Andorhal (grain distribution point, cult infected grain sent to northern villages, Araj headquarters)'),
(2806, 1, 0, 255, 'The parcel reached her kin at last. It held half of a luck charm, and only when her husband John''s half was found on the farm and the charm made whole did Janice''s ghost find peace.', 'quests 5216, 5229 descriptions (northwest of Andorhal, greener troops, should not be underestimated)'),
(2807, 1, 0, 255, 'The diary told the family''s end. When Harold Dalson turned, his wife locked him in the outhouse and meant to flee, but she never left: the wandering skeleton was hers, the key still on her bones.', 'warcraft.wiki.gg/wiki/Dalson%27s_Tears (formerly Dalson''s Orchard; Cauldron Lord Malvinious; Mrs. Dalson roams as a Wandering Skeleton)'),
(2808, 1, 0, 255, 'Sensing his end, Mulgris wrote what he had learned of the plague into a glyphed oaken branch meant for the Cenarion Circle. Then, with the suffering beasts at rest, he lay still on the cottage floor.', 'quests 5222, 5233 descriptions (almost due east of Andorhal, close to the ruined city walls)'),
(2808, 2, 0, 255, 'The branch reached the Cenarion Circle, and in its glyphs the druids found a great store of lore about the Scourge''s plague. They promised that his work would not be wasted.', 'quests 5222, 5233 descriptions (almost due east of Andorhal, close to the ruined city walls)'),
(2816, 1, 0, 255, 'He is the son of Tirion Fordring. After Tirion''s exile his mother told him his father was dead. He became a paladin of the Silver Hand, threw down its standard at Northdale when the order broke, and rose in the Crusade.', 'quest 5781 description (his mother told him Tirion had died)'),
(2816, 2, 0, 255, 'For years, he confessed, he had been the Grand Crusader''s puppet. Shown the truth, he left Hearthglen to find his father, and Grand Inquisitor Isillien cut him down on the road.', 'quest 5781 description (his mother told him Tirion had died)');
