INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Hint`, `Sources`) VALUES
(6600, 0, 66, 0, 0, 13, 'Zul''Drak', 'Zul''Drak is the heartland of the Drakkari, a vast temple city of ziggurats, walls and aqueducts climbing in great tiers, with Gundrak, the capital of their empire, at its heart. The empire is dying. The Scourge presses in from every side, raising necropolises over the lower tiers, and in their desperation the Drakkari have turned on their own animal gods, slaying them at their altars so their prophets may drink the gods'' power. Between the two stand the Argent Crusade and the death knights of the Ebon Blade.', '', 'warcraft.wiki.gg/wiki/Zul''Drak (temple city of ziggurats, walls and aqueducts between the Grizzly Hills, Crystalsong Forest and the Storm Peaks; Gundrak the capital; Argent Stand, Light''s Breach, Ebon Watch, Zim''Torga); npc_text 13615 (Lantinga: the trolls sacrificed their animal gods to drink their blood and hold back the Scourge; the empire lies in ruin); npc_text 13046 (Falstaav: the Scourge on one side, the Drakkari rituals on the other); quests 12623, 12707 (great steps to the next tier), 12516 reward text (higher tiers); npc_text 13282 (To''kini: the Zandalari witness the end of an empire); quest 12884 (Ebon Watch, death knights); zone_areas: necropolises Kolramas (crashed), Voltarus, Zeramas'),
(6601, 1, 66, 0, 0, 13, 'Light''s Breach', 'Light''s Breach is an Argent Crusade camp southwest of the Argent Stand, raised among ruins where every troll is dead or fled, cut off from the Stand by the Scourge. Wolvar of the Rageclaw tribe shelter there with their pups: for thousands of years they lived beside the Drakkari as allies, until the trolls fell on their den to the southeast.', '', 'zone_areas 4317 (Riannah 29137, Lantinga 29687, Chief Rageclaw 29690, Elder Shaman Moky 29733, Rageclaw Pup 29848, Light''s Breach Defender); npc_text 13615 (Lantinga: every troll here dead or fled to the upper levels); quest 12792 description (Scourge forced their way between Kunz and Riannah, leaving her isolated; Light''s Breach southwest of the Stand); quests 12770, 12763, 12789, 12793 descriptions (Scourge making a push to take Zul''Drak; report to Riannah); quests 12859, 12861 descriptions (Rageclaw driven out of their den by trolls); quest 12902 description (Rageclaw allied with the Drakkari for thousands of years; attack took them by surprise; den southeast); quests 12859, 12861 descriptions (den burning; captured Rageclaw; trolls call themselves Drakuru trolls); quest 12857 description (Ragemane, the chief''s lion seal, gone bad; at Rageclaw Lake); zone_areas 4316 (Hut Fire, Captured Rageclaw, Drakuru Shackles, Drakuru Blood Drinker, Berserker, Prophet), 4374 (Ragemane 29664); npc_text 13615; quest 12883 reward text (half our army tied up at the Argent Stand); quest 12902 description'),
(6605, 1, 66, 0, 0, 13, 'The Dead Fields', 'The Dead Fields stretch north of Light''s Breach, and the Scourge runs them as a factory: corpses lie in rows, banshees drift overhead, and the dead of Zul''Drak are gathered to be sent up to the necropolis Zeramas and made into Scourge. A Crusade forward camp on its border was overrun by them. Northwest of it lies Thrym''s End, a base of the Scourge''s vargul, where the king of the storm giants rages in a hundred-foot cage.', '', 'quest 12883 description (corpses processed in the Dead Fields and sent up to Prince Navarius'' crew in Zeramas); quest 12894 reward text (factory for Scourge); quest 12901 description (zombie factory); zone_areas 4468 (Field Corpse, Reanimated Corpse, Banshee Soulclaimer), 4469 (Crusader Dargath 29468, Vargul Slayer, Banshee Soulclaimer); quest 12901 description (Thrym''s End northwest of the camp; Scourge base; scrap metal from their arrival); quest 12904 description (tables for experiments on the other side of the camp); quest 12914 description (cage 100 foot tall); zone_areas 4313 (Vargul Slayer, Runelord, Deathwaker, Plaguetalon, Blighthound; Gymer Lock Dummy; Gerk, Burr); creature_text 29647 group 1 (Gymer''s taunts from the cage); quest 12894 description (Dargath, MacKellar, Reed and the twins Gerk and Burr sent to the Dead Fields; camp on the border, northwest of Light''s Breach); zone_areas 4489 (MacKellar 29689, Reed 29688, Reed''s Steam Tank 29691); quest 12901 description (getting the tank operational); quest 12894 description (last correspondence: camp successfully established); quest 12912 description; quest 12919 description (flesh giants from storm giant corpses; Thrym); zone_areas 4313 (Gymer 29647)'),
(6606, 1, 66, 0, 0, 13, 'Ebon Watch', 'Ebon Watch is the camp of the Knights of the Ebon Blade in western Zul''Drak, raised to hunt the Scourge they once served. Stefan Vadu commands it, holding that none know the Scourge better than death knights and that the best weapon against fire is fire.', '', 'zone_areas 4312 (Stefan Vadu 28518, Bloodrose Datura 28532, Captured Drakkari Scout 28541, Corrosion, Spiked, Mulch, Deathdrip, Corpsedust, Scabbard, Squirmworm, Baneflight 28615, Ebon Watch Guardian); npc_text 13270 (Stefan: none know the Scourge better than death knights; fire with fire); quest 12630 description (Nass, blighted, deaf, blind and numb); quest 12884 description (death knight encampment west of Light''s Breach); quest 12884 reward text (Argent Crusade late to the party; tracking Drakuru); npc_text 13270; quest 12630 description (Nass); quest 12629 description (use their desires against them); warcraft.wiki.gg/wiki/Stefan_Vadu (human death knight, Ebon Blade); quest 12884 reward text; quests 12631, 12633 descriptions and reward text; creature_loot_template 28519 (Withered Troll: Unliving and Writhing Chokers)'),
(6607, 1, 66, 0, 0, 13, 'Voltarus', 'Over the blighted pools of northwestern Zul''Drak hang two necropolises. Voltarus hovers above the Reliquary of Pain, where blight geists harvest crystals of blight and abominations lurch among blight cauldrons, and it is the seat of Overlord Drakuru. To the southwest Zeramas hangs over the Reliquary of Agony. North of Voltarus, at the Frigid Breach, a Drakkari army has broken through the wall.', '', 'warcraft.wiki.gg/wiki/Voltarus (hovers over the Reliquary of Pain; Drakuru''s necropolis); warcraft.wiki.gg/wiki/Zeramas (necropolis over the Reliquary of Agony); quests 12673 (blight crystals harvested from the land below), 12652 (Gristlegut feeding the ghouls), 12690 description (trolls breached the wall, army just north); quest 12648 description (blightguards see through disguises); zone_areas 4315 (Blight Geist, Bloated Abomination, Servant of Drakuru, Blightguard, Blight Cauldron and Scourgewagon bunnies on the ground, z 230-250); quests 12669, 12676 descriptions (blight cauldrons, scourgewagons at the Reliquary of Pain)'),
(6608, 1, 66, 0, 0, 13, 'The Argent Stand', 'The Argent Stand is the Argent Crusade''s stronghold in the lower city, a terrace above a courtyard where the fighting against the Scourge never ends, held between the Scourge on one side and the Drakkari rituals on the other. A Zandalari hexxer counsels its commanders, and the old orc Eitrigg stands among them. To the southeast lies Kolramas, a necropolis the Drakkari somehow brought down out of the sky, its wreck still full of nerubians and strewn with saronite.', '', 'zone_areas 4275 (Kunz 28039, Falstaav 28059, Ubungo 28062, Korfax 28175, Rimblat 28176, Rayne 28177, Metz 28178, Eitrigg 28244, Sky Terror, Argent Crusader); quests 12503 (courtyard below, no end to the fighting), 12740 (sky terrors drop crusaders); npc_text 13043 (Kunz), 13046 (Falstaav), 13050 (Ubungo, Zandalar tribe), 14284 (Korfax: overdue in Icecrown, told the highlord it was a mistake), 14285 (Rimblat), 14286 (Rayne: the Plaguelands and Light''s Hope); quest 12596 description (Kunz); quest 12552 description (trolls brought down Kolramas; it crashed next to us; raising our men); npc_text 13117 (Moonshard: how did they manage to do that); quest 12554 description (Malas the Corrupter gloating atop); quest 12553 description (plague sprayers); quest 12584 description (saronite strewn within); zone_areas 4299 (Hath''ar Skimmer, Necromagus, Plague Sprayer, Malas 28255, Chunk of Saronite); quest 12512 description (pushed back; lost Drak''Sotra to the Scourge; find the wounded); quests 12502, 12509, 12568, 12598 descriptions (banners, cowering recruits, burning the fallen, nerubian tunnels); quest 12510 description (Drak''Sotra Fields; the wall between worlds weakened, elementals flooding in); quest 12562 description (Drakkari water binders); quest 12564 (poppies the trolls cultivate); zone_areas 4279, 4278; quest 12799 description (Finklestein the Crusade''s best alchemist; pools of spirits of ancient trolls just south); quest 12610 description (Arnath relegated); quests 12599, 12594 descriptions (Grondel: knee-deep in stagnant water; thornwood; sewage elementals); quest 12527 description (basilisks at Drak''Agal); zone_areas 4294 (Finklestein 28205, Arnath 28045, reagents), 4280, 4318 (Lost Drakkari Spirit, Disturbed Soul)'),
(6609, 1, 66, 0, 0, 13, 'Altar of Sseratus', 'At the end of the avenue north of the Argent Stand rises the Altar of Sseratus, the snake god''s holy place. Its priests and champions still crowd the steps, and a prophet holds court before the main building, boasting that with the power of the wild gods in their veins not even the Lich King can stand against them.', '', 'quest 12505 description (altar up the avenue, Stackhammer); quest 12506 description (altar of the snake god; avoid the prophet); creature_text 28068 group 2 (prophet''s boasts); creature_text 28041 group 0 (soldiers); zone_areas 4276 (Priest, Champion of Sseratus, Snake Handler, Prophet 28068, Sseratus 28089, Stackhammer 28056, Corporal Maga 28099, Argent Soldier); quest 12506 description (presence of the Scourge weakened the land and the wild gods; Drakkari take advantage); quest 12623 description (Zandalari must stop what the Drakkari are doing to their gods); npc_text 14285 (Rimblat), 13176 (Khufu), 13615 (Lantinga); creature_text 28068 group 2'),
(6615, 1, 66, 0, 0, 13, 'Zim''Torga', 'Up the great steps on the next tier of the city lies Zim''Torga, a refuge the Zandalari have taken beneath the statue of the Mother of Prosperity, come from Zandalar to defend the gods who still live. Around them altar after altar has fallen: the snow leopard goddess Har''koa is held by her own subduers, the bear god Rhunok is kept close to death, and something is wrong at the altar of the wind serpent.', '', 'quest 12623 description (Zim''Torga up the great steps to the northeast; refuge the Zandalari defend; constant attack); quest 12615 description (refuge within the presence of Zim''Torga, Mother of Prosperity); npc_text 13180 (Dagoda: Zim''Torga weakened by the Scourge and the Drakkari), 13234 (Ahunae), 13282 (To''kini); quest 12639 description (captured elementals as defenders); zone_areas 4323; quest 12632 description (last of the gods to be subdued; bound by magic; offspring transformed into monstrosities); quest 12666 description (subduers and claws); quest 12635 description (relics); zone_areas 4322 (Har''koa 28401, Har''koan Subduer, Claw of Har''koa, Cursed Offspring, Prophet of Har''koa 28848, Har''koan Relic); quest 12642 description (altar northwest beyond Drak''Mabwa); npc_text 13291 (body kept close to death in the altar building); creature_text 28575 (tormentor: keep him weak so the prophet can finish); quest 12650 description (plundered their own holy site); quests 12639, 12640 (frozen earth, elemental rifts at Drak''Mabwa); quest 12646 description (crater to the south in Drak''Mabwa); zone_areas 4321, 4327; quest 12665 description (something wrong with Quetz''lun; altar overrun with powerful creatures); zone_areas 4325 (Scion of Quetz''lun, Altar Warden, Quetz''lun Worshipper, Serpent-Touched Berserker, Prophet 28671, Quetz''lun 28672); quest 12707 description (what''s left of the Altar of Mam''toth; enraged mammoths; disciples); quest 12684 description (crater north of the Altar of Quetz''lun; his blood yet lives); zone_areas 4329 (Dead Mam''toth Disciple, Mam''toth Disciple, Enraged Mammoth), 4371 (Blood of Mam''toth 28779); creature positions: Blood of Mam''toth (x 6018) north of the altar (x 5717), Mam''toth Disciples (x 6259) beyond; quest 12632 description (last of the gods to be subdued; bound; offspring transformed); quest 12628 description and reward text (the gods have spoken; speak with the leopard goddess; time is of the essence); creature 28401 (spawns at the Altar of Har''koa and Zim''Torga, both in Zul''Drak); npc_text 13176 (power transitory, lost for all eternity); quest 12627 description (communing with the gods; medicine men interfering); creature_text 28479 (beseeching the gods); quest 12623 reward text; quest 12665 description; creature_text 28665'),
(6622, 1, 66, 0, 0, 13, 'Gundrak', 'Gundrak is the capital of the Drakkari Empire, a great palace city whose trolls swarm its approaches. In the courtyard before its gates Akali, the rhino god, lies in chains at four anchor points while his subduers prepare him for slaughter. Beside the city a few Zandalari keep watch from Dubra''Jin, observing and recording what they see.', '', 'quest 12721 description (Akali held in the courtyard before Gundrak, capital of Zul''Drak; four anchor points; teeming with ice trolls); quest 12712 description (being prepared for slaughter); quest 12730 description (Zol''Heb just south of Gundrak; circle of power); quest 13099 description (post just west of Gundrak); zone_areas 4375 (Akali 28952, Akali Subduer, Gundrak Fire-eater, Brute, Bat Rider, Akali Chain Anchor), 4373, 4579 (Tol''mar, Bah''Kini, Ha''wana); quest 13097 description (Dubra''Jin north of Gundrak); quest 13096 offer text (Tol''mar''s job to observe only); quest 12506 description (presence of the Scourge weakened the land and the wild gods; Drakkari take advantage); quest 12623 description (Zandalari must stop what the Drakkari are doing to their gods); npc_text 14285 (Rimblat), 13176 (Khufu), 13615 (Lantinga); creature_text 28068 group 2'),
(6623, 2, 66, 0, 0, 13, 'Overlord Drakuru', 'Overlord Drakuru commands the Scourge in Zul''Drak from the necropolis Voltarus. He is a Drakkari himself, and by his own orders the Lich King has given him full control of the Scourge''s armies here. The trolls who follow him call themselves the Drakuru, and he promises that he will soon drink the blood of the prophets and see Zul''Drak and Gundrak fall.', '', 'quest 12883 description (Orders From Drakuru); quest 12884 reward text (tracking Drakuru since the Grizzly Hills; slated for eradication); npc_text 13348 (another supplicant seeking the Lich King''s favors); creature 28503 (Voltarus, phase 1, gossip 9731); warcraft.wiki.gg/wiki/Drakuru; quest 12884 reward text; quests 12631, 12633 descriptions and reward text; creature_loot_template 28519 (Withered Troll: Unliving and Writhing Chokers)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(6601, 1, 0, 255, 'The attack was no troll quarrel. Orders above an altar in the den came from Drakuru himself: the Lich King had given him full control of the Scourge''s armies in Zul''Drak, and everything was to die.', 'zone_areas 4317 (Riannah 29137, Lantinga 29687, Chief Rageclaw 29690, Elder Shaman Moky 29733, Rageclaw Pup 29848, Light''s Breach Defender)'),
(6605, 1, 0, 255, 'The storm giant king came at a cry for help from his brother, only to find it a trap: his brother is now an undead servant of the Lich King, and the Scourge stitches the corpses of his people into flesh giants.', 'quest 12883 description (corpses processed in the Dead Fields and sent up to Prince Navarius'' crew in Zeramas)'),
(6606, 1, 0, 255, 'A choker of bone found on a dead troll compels whoever finds it to serve the Scourge, and is never wasted on a random target. Stefan turned the snare around into a disguise to walk among the Scourge.', 'zone_areas 4312 (Stefan Vadu 28518, Bloodrose Datura 28532, Captured Drakkari Scout 28541, Corrosion, Spiked, Mulch, Deathdrip, Corpsedust, Scabbard, Squirmworm, Baneflight 28615, Ebon Watch Guardian)'),
(6606, 2, 0, 255, 'Stefan has little patience for the Argent Crusade, late to the party once again. The knights'' quarry here is Overlord Drakuru, whom they have tracked since the Grizzly Hills.', 'zone_areas 4312 (Stefan Vadu 28518, Bloodrose Datura 28532, Captured Drakkari Scout 28541, Corrosion, Spiked, Mulch, Deathdrip, Corpsedust, Scabbard, Squirmworm, Baneflight 28615, Ebon Watch Guardian)'),
(6607, 1, 0, 255, 'In an upper chamber stand Drakuru''s secret weapons: Blightblood trolls, the makings of the ultimate Scourge army with which he means to take the palace of Gundrak.', 'warcraft.wiki.gg/wiki/Voltarus (hovers over the Reliquary of Pain; Drakuru''s necropolis)'),
(6608, 1, 0, 255, 'Saronite from the fallen necropolis was put to the test: an axe failed to scratch it, the elements and nature could not touch it, and the Light knocked them all back. Its secrets must be unlocked before it is too late.', 'zone_areas 4275 (Kunz 28039, Falstaav 28059, Ubungo 28062, Korfax 28175, Rimblat 28176, Rayne 28177, Metz 28178, Eitrigg 28244, Sky Terror, Argent Crusader)'),
(6609, 1, 0, 255, 'Inside lies Sseratus, slain by his own worshippers, who have drunk deeply of his mojo, the prophet most of all.', 'quest 12505 description (altar up the avenue, Stackhammer)'),
(6615, 1, 0, 255, 'Rather than let his trolls drink his power, the mammoth god Mam''toth destroyed himself and much of his temple with him, leaving a crater where his blood still lives.', 'quest 12623 description (Zim''Torga up the great steps to the northeast; refuge the Zandalari defend; constant attack)'),
(6615, 2, 0, 255, 'Having given part of her spirit so that Quetz''lun could be avenged, Har''koa left her altar and now dwells in the Zandalari refuge.', 'quest 12623 description (Zim''Torga up the great steps to the northeast; refuge the Zandalari defend; constant attack)'),
(6622, 1, 0, 255, 'Akali was freed, and at once his prophet slew him, claiming his blood for his master and some of his power for himself, and swore he was coming for Har''koa next.', 'quest 12721 description (Akali held in the courtyard before Gundrak, capital of Zul''Drak; four anchor points; teeming with ice trolls)'),
(6623, 1, 0, 255, 'To those who helped him in the Grizzly Hills he speaks as an old friend: the choker that called them to Voltarus was his gift, and now they serve the Lich King side by side.', 'quest 12883 description (Orders From Drakuru)'),
(6623, 2, 0, 255, 'His trust was his undoing. His Blightbloods were turned against him, and the Lich King came, but only to condemn him for his failure and strike him dead.', 'quest 12883 description (Orders From Drakuru)');
